void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = (fragCoord * 2.0 - iResolution.xy) / min(iResolution.x, iResolution.y);
    float time = iTime * 0.5;

    // Color cycling
    float cycleSpeed = 0.3;
    vec3 startColor = 0.5 + 0.5 * sin(time * cycleSpeed + vec3(0.0, 1.0, 2.0)); // RGB cycle
    vec3 endColor = 0.5 + 0.5 * sin((time * cycleSpeed + 1.0) + vec3(3.0, 2.0, 1.0)); // Different phase for end color

    // Primary pattern parameters
    float spiralFactor = 0.5 + 0.5 * sin(time * 0.3);
    float radius = 0.6 + 0.2 * sin(time * 0.5);

    // Mouse interaction
    if (iMouse.z > 0.0) { // Check if mouse is down
        spiralFactor = (iMouse.x / iResolution.x) * 2.0;
        radius = (iMouse.y / iResolution.y) * 0.9 + 0.1;
        cycleSpeed *= 2.0;
    }

    float angle = atan(uv.y, uv.x);
    float dist = length(uv);

    // Spiral pattern
    float spiral = mod(angle + spiralFactor * dist * 5.0, 6.2831853);
    float wave = sin(spiral * 5.0 + time);
    float modifiedDist = dist + wave * 0.1;

    // Color transition
    float colorRatio = smoothstep(0.0, radius, modifiedDist);
    vec3 col = mix(startColor, endColor, colorRatio);

    // Grid 
    float gridSize = 0.4 + 0.05 * sin(time * 0.2);
    vec2 gridUV = fract(uv * (1.0 / gridSize));
    float gridDistortion = sin(modifiedDist * 20.0 + time) * 0.05;
    vec2 distortedGridUV = gridUV + vec2(gridDistortion);
    float grid = sin(distortedGridUV.x * 3.14159) * sin(distortedGridUV.y * 3.14159);
    grid = abs(grid); 
    col = mix(col, vec3(1.0 - grid), 0.1);

    // Coral growth 
    float coralGrowth = 0.0;
    for (int i = 0; i < 5; i++) { // Number of growth layers
        float phase = float(i) * 0.2;
        vec2 growthUV = uv + vec2(sin(time * 0.1 + phase), cos(time * 0.15 + phase)) * 0.1;
        float growth = sin(length(growthUV * (10.0 + 5.0 * sin(time * 0.05))) - time * 0.5);
        coralGrowth += max(0.0, growth) * (0.5 - float(i) * 0.1); // Each layer less intense
    }
    coralGrowth /= 5.0; // Normalize growth effect

    // Blend coral growth with existing color
    vec3 coralColor = vec3(0.8, 0.5, 0.3); // Coral-like color
    col = mix(col, coralColor * (1.0 + coralGrowth), coralGrowth * 0.5);

    // Adjust for brightness and contrast
    col = col * (1.0 + 0.5 * sin(time * 0.1)) * 1.5;
    col = clamp(col, 0.0, 1.0);



    // Vignette effect
    float vignette = 1.0 - smoothstep(0.0, 1.9, length(uv));
    col *= vignette;

    fragColor = vec4(col, 1.0);
}
